import{_ as i,o as a,c as e,ag as t}from"./chunks/framework.CrXGS008.js";const c=JSON.parse('{"title":"配套扩展服务","description":"","frontmatter":{},"headers":[],"relativePath":"guide/extension.md","filePath":"guide/extension.md","lastUpdated":1789979194000}'),n={name:"guide/extension.md"};function l(p,s,h,o,d,r){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="配套扩展服务" tabindex="-1">配套扩展服务 <a class="header-anchor" href="#配套扩展服务" aria-label="Permalink to &quot;配套扩展服务&quot;">​</a></h1><p>核心监控不需要额外服务。服务器媒体库、公开媒体直链下载、持久化播放列表和手动节点检测由配套扩展提供。</p><h2 id="需要准备" tabindex="-1">需要准备 <a class="header-anchor" href="#需要准备" aria-label="Permalink to &quot;需要准备&quot;">​</a></h2><ul><li>Node.js 24.15 或更高的 24 / 26 版本。</li><li>可访问 Komari 的服务器，以及同域反向代理。</li><li>需要视频转码时安装 FFmpeg。</li></ul><p>从 Release 下载 <code>-extension.zip</code>，解压到独立目录，安装依赖：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-scripts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-audit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-fund</span></span></code></pre></div><p>环境配置示例：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DS_KOMARI_ORIGIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=http://127.0.0.1:25774</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DS_PUBLIC_ORIGIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://monitor.example.com</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DS_DATA_DIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/var/lib/komari-ds</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DS_BIND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DS_PORT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=5175</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DS_ENABLE_JOBS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=false</span></span></code></pre></div><p>通过随包提供的 systemd 或 Docker 示例持续运行。将 <code>/komari-ds-api/</code> 代理到 <code>127.0.0.1:5175</code>，再到主题设置的扩展服务页检查连接。<a href="https://github.com/fanchengliu/komari-next-pro/blob/main/docs/EXTENSION.md" target="_blank" rel="noreferrer">完整配置与权限说明</a></p><h2 id="节点检测" tabindex="-1">节点检测 <a class="header-anchor" href="#节点检测" aria-label="Permalink to &quot;节点检测&quot;">​</a></h2><p>需要检测时显式启用 <code>DS_ENABLE_JOBS=true</code>，并允许相应 Komari Agent 执行任务。页面按钮只对选中节点下发固定任务，不自动批量执行。</p><p>IP 归属分别记录 IPv4 和 IPv6 成功或失败原因。参考估算无需质量 Key，基于已取得的资料计算，能展开查看规则。真实 VPN、代理、Tor 等数据源指标需要服务端配置相应质量服务。</p><div class="warning custom-block"><p class="custom-block-title">密钥位置</p><p><code>DS_KOMARI_API_KEY</code>、<code>DS_IPAPI_KEY</code> 只放在服务端环境中，不能填进公开主题配置或提交到仓库。</p></div><p>升级扩展时保留原数据目录与环境文件，先备份 SQLite 和媒体库，再切换代码目录。两代 Next Pro 扩展 API 不应互相覆盖。</p>`,14)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
